package com.brannenservices.fieldassistant

import android.app.Activity
import android.graphics.*
import android.os.Bundle
import android.view.*
import kotlin.math.*

class MainActivity : Activity() {
 override fun onCreate(b:Bundle?){super.onCreate(b);requestWindowFeature(Window.FEATURE_NO_TITLE);window.setFlags(1024,1024);window.decorView.systemUiVisibility=5894;setContentView(GameView(this))}
 class GameView(activity:Activity):View(activity){
  data class Bird(var x:Float,var hp:Int,val max:Int,val boss:Boolean=false,var hit:Int=-1,var flash:Float=0f)
  data class Beer(val x:Float,var taken:Boolean=false)
  val W=640; val H=360; val G=278f; val WORLD=3000f
  val bmp=Bitmap.createBitmap(W,H,Bitmap.Config.ARGB_8888); val bc=Canvas(bmp)
  val p=Paint().apply{isAntiAlias=false}; val screen=Paint().apply{isAntiAlias=false;isFilterBitmap=false}
  var px=105f;var py=G;var vy=0f;var cam=0f;var face=1;var joy=0f;var joyId=-1
  var started=false;var dead=false;var won=false;var hp=100;var score=0;var cans=0;var attack=0f;var attackId=0;var hurt=0f;var t=0f;var last=System.nanoTime();var combo=0;var comboT=0f;var wave=1;var msg="";var msgT=0f
  val birds=mutableListOf(Bird(470f,2,2),Bird(760f,2,2),Bird(1080f,3,3),Bird(1450f,3,3),Bird(1880f,4,4),Bird(2470f,12,12,true))
  val beers=mutableListOf(Beer(650f),Beer(1330f),Beer(2050f))
  override fun onDraw(c:Canvas){val n=System.nanoTime();val dt=((n-last)/1e9f).coerceAtMost(.04f);last=n;if(started&&!dead&&!won)update(dt);drawGame();c.drawBitmap(bmp,null,Rect(0,0,width,height),screen);postInvalidateOnAnimation()}
  fun update(dt:Float){t+=dt;attack=max(0f,attack-dt);hurt=max(0f,hurt-dt);comboT=max(0f,comboT-dt);msgT=max(0f,msgT-dt);if(comboT<=0f)combo=0
   if(abs(joy)>.12f){face=if(joy>0f)1 else -1;px=(px+joy*220f*dt).coerceIn(30f,WORLD-40f)}
   vy+=780f*dt;py+=vy*dt;if(py>G){py=G;vy=0f};cam+=(px-235f-cam)*min(1f,dt*7f);cam=cam.coerceIn(0f,WORLD-W);wave=if(px<1000f)1 else if(px<2000f)2 else 3
   birds.forEach{b->b.flash=max(0f,b.flash-dt);if(b.hp<=0)return@forEach;val dx=px-b.x;if(abs(dx)<(if(b.boss)390f else 260f))b.x+=(if(dx>0f)1f else -1f)*(if(b.boss)78f else 55f)*dt
    if(attack>0f&&b.hit!=attackId){val d=(b.x-px)*face.toFloat();if(d in 5f..105f&&py>G-90f){b.hp--;b.hit=attackId;b.flash=.1f;b.x+=face.toFloat()*(if(b.boss)20f else 38f);combo++;comboT=1.3f;score+=(if(b.boss)250 else 100)*(1+(combo-1)/3);say(if(combo>2)"$combo HIT COMBO!" else "BONK!");if(b.hp<=0)score+=if(b.boss)1800 else 300}}
    if(abs(b.x-px)<(if(b.boss)48f else 31f)&&py>G-55f&&hurt<=0f){hp=max(0,hp-(if(b.boss)18 else 10));hurt=.7f;px+=if(dx>0f)-55f else 55f;if(hp<=0)dead=true}}
   beers.forEach{if(!it.taken&&abs(it.x-px)<34f&&py>G-70f){it.taken=true;cans++;hp=min(100,hp+25);score+=200;say("COLD ONE ACQUIRED!")}}
   if(birds.last().hp<=0&&px>2780f)won=true
  }
  fun say(s:String){msg=s;msgT=1.1f}
  fun col(v:Int){p.color=v;p.style=Paint.Style.FILL;p.shader=null}
  fun rect(c:Canvas,l:Float,top:Float,r:Float,b:Float,v:Int){col(v);c.drawRect(l,top,r,b,p)}
  fun txt(c:Canvas,s:String,x:Float,y:Float,size:Float,v:Int,center:Boolean=false){col(v);p.typeface=Typeface.create(Typeface.MONOSPACE,Typeface.BOLD);p.textSize=size;p.textAlign=if(center)Paint.Align.CENTER else Paint.Align.LEFT;c.drawText(s,x,y,p);p.textAlign=Paint.Align.LEFT}
  fun drawGame(){rect(bc,0f,0f,W.toFloat(),H.toFloat(),Color.rgb(39,31,84));sky();distant();dock();props();beers.filter{!it.taken}.forEach{beer(it)};birds.filter{it.hp>0}.forEach{flamingo(it)};man();hud();controls();if(!started)panel("POOL NOODLE PANIC","TAP TO START THE BAD DECISIONS");if(dead)panel("WELL, THAT WENT BAD","TAP TO TRY AGAIN");if(won)panel("ALPHA FLAMINGO DEFEATED","TAP FOR ANOTHER BAD IDEA");if(msgT>0f){rect(bc,180f,305f,460f,331f,Color.rgb(17,16,30));txt(bc,msg,320f,323f,12f,Color.YELLOW,true)}}
  fun sky(){p.shader=LinearGradient(0f,25f,0f,220f,Color.rgb(55,39,115),Color.rgb(255,102,73),Shader.TileMode.CLAMP);bc.drawRect(0f,25f,640f,220f,p);p.shader=null;col(Color.rgb(255,184,50));bc.drawCircle(465f,142f,42f,p);rect(bc,425f,142f,505f,146f,Color.rgb(255,210,76));for(i in 0..5)rect(bc,400f+i*22f,151f+(i%2)*5f,510f-i*12f,154f+(i%2)*5f,Color.rgb(255,150,69))}
  fun distant(){val off=-(cam*.08f%180f);for(i in -1..4){val x=off+i*180f;rect(bc,x+75f,126f,x+80f,220f,Color.rgb(24,44,65));col(Color.rgb(16,57,55));for(a in -2..2){val q=Path();q.moveTo(x+78f,128f);q.lineTo(x+78f+a*29f,112f+abs(a)*6f);q.lineTo(x+83f+a*12f,133f);q.close();bc.drawPath(q,p)}};rect(bc,0f,190f,640f,224f,Color.rgb(19,91,126));for(i in 0..9){val x=i*79f-(cam*.13f%79f);rect(bc,x,201f,x+43f,204f,Color.rgb(255,143,88));rect(bc,x+12f,212f,x+62f,214f,Color.rgb(92,166,175))}
   val hx=45f-(cam*.2f%1050f);rect(bc,hx,139f,hx+150f,220f,Color.rgb(44,63,75));rect(bc,hx+8f,151f,hx+142f,215f,Color.rgb(64,84,91));col(Color.rgb(31,31,43));val roof=Path();roof.moveTo(hx-10f,151f);roof.lineTo(hx+72f,113f);roof.lineTo(hx+160f,151f);roof.close();bc.drawPath(roof,p);for(i in 0..3){rect(bc,hx+18f+i*32f,168f,hx+35f+i*32f,192f,Color.rgb(255,197,74));rect(bc,hx+21f+i*32f,171f,hx+32f+i*32f,189f,Color.rgb(255,231,138))}}
  fun dock(){rect(bc,0f,224f,640f,279f,Color.rgb(78,52,39));for(i in 0..10){val x=i*66f-(cam*.65f%66f);rect(bc,x,224f,x+58f,272f,if(i%2==0)Color.rgb(139,88,52) else Color.rgb(119,72,47));rect(bc,x,229f,x+58f,233f,Color.rgb(181,117,63));rect(bc,x+7f,270f,x+15f,315f,Color.rgb(57,42,36));rect(bc,x+4f,306f,x+19f,312f,Color.rgb(36,29,31))};rect(bc,0f,279f,640f,360f,Color.rgb(12,74,96));for(i in 0..8){val x=i*91f-(cam*.4f%91f);rect(bc,x,300f,x+53f,303f,Color.rgb(37,134,148));rect(bc,x+30f,330f,x+76f,333f,Color.rgb(20,103,128))}}
  fun props(){sign(360f,"GOOD BEER","BAD IDEAS");sign(1660f,"NO WAKE","JUST CHAOS");sign(2750f,"BEWARE","GATORS");val gx=2210f-cam;if(gx in -100f..700f){col(Color.rgb(22,70,48));bc.drawOval(gx-50f,292f,gx+55f,322f,p);rect(bc,gx+26f,286f,gx+82f,305f,Color.rgb(22,70,48));rect(bc,gx+72f,291f,gx+92f,296f,Color.rgb(238,222,160));rect(bc,gx+77f,301f,gx+94f,305f,Color.WHITE);rect(bc,gx+55f,289f,gx+59f,293f,Color.YELLOW)}}
  fun sign(wx:Float,a:String,b:String){val x=wx-cam;if(x !in -100f..740f)return;rect(bc,x-3f,184f,x+3f,225f,Color.rgb(62,38,27));rect(bc,x-48f,164f,x+48f,184f,Color.rgb(188,135,73));txt(bc,a,x,174f,8f,Color.rgb(37,27,26),true);txt(bc,b,x,182f,8f,Color.rgb(37,27,26),true)}
  fun man(){if(hurt>0f&&(hurt*12f).toInt()%2==0)return;val x=px-cam;val y=py;val bob=if(abs(joy)>.12f&&py>=G)sin(t*13f)*2f else 0f;val skin=Color.rgb(221,145,91);val dark=Color.rgb(52,34,30);rect(bc,x-13f,y-5f+bob,x-3f,y+21f+bob,skin);rect(bc,x+5f,y-5f-bob,x+15f,y+21f-bob,skin);rect(bc,x-17f,y+17f+bob,x-1f,y+22f+bob,Color.rgb(35,35,35));rect(bc,x+2f,y+17f-bob,x+19f,y+22f-bob,Color.rgb(35,35,35));rect(bc,x-19f,y-32f,x+19f,y+2f,Color.rgb(35,82,145));for(i in 0..3)rect(bc,x-15f+i*9f,y-27f+(i%2)*7f,x-9f+i*9f,y-21f+(i%2)*7f,Color.WHITE);rect(bc,x-18f,y-70f,x+18f,y-31f,Color.rgb(238,235,214));rect(bc,x-14f,y-65f,x+14f,y-35f,Color.WHITE);rect(bc,x-20f,y-62f,x-13f,y-35f,skin);rect(bc,x+13f,y-62f,x+21f,y-35f,skin);rect(bc,x-16f,y-98f,x+16f,y-70f,skin);rect(bc,x-19f,y-96f,x-14f,y-70f,dark);rect(bc,x-17f,y-103f,x+13f,y-96f,Color.rgb(226,218,186));rect(bc,x+11f,y-100f,x+23f,y-96f,Color.rgb(226,218,186));rect(bc,x-13f,y-91f,x-1f,y-85f,Color.BLACK);rect(bc,x+2f,y-91f,x+14f,y-85f,Color.BLACK);rect(bc,x-1f,y-89f,x+3f,y-87f,Color.rgb(45,45,45));rect(bc,x+5f,y-78f,x+16f,y-74f,dark);rect(bc,x-12f,y-72f,x+10f,y-69f,dark);val sx=x+face*17f;val sy=y-51f;col(Color.rgb(37,164,255));p.strokeWidth=9f;p.strokeCap=Paint.Cap.SQUARE;if(attack>0f){val a=(1f-attack/.2f).coerceIn(0f,1f);val deg=if(face>0)-55f+a*95f else 235f-a*95f;val r=Math.toRadians(deg.toDouble());bc.drawLine(sx,sy,sx+cos(r).toFloat()*82f,sy+sin(r).toFloat()*82f,p)}else bc.drawLine(sx,sy,x+face*52f,y-70f,p)}
  fun flamingo(b:Bird){val x=b.x-cam;if(x !in -100f..740f)return;val s=if(b.boss)1.55f else 1f;val y=G;val pink=if(b.flash>0f)Color.WHITE else if(b.boss&&b.hp<=6)Color.rgb(226,38,71) else Color.rgb(244,74,128);col(pink);bc.drawOval(x-24f*s,y-45f*s,x+25f*s,y-18f*s,p);rect(bc,x+8f*s,y-62f*s,x+15f*s,y-31f*s,pink);rect(bc,x+12f*s,y-77f*s,x+19f*s,y-57f*s,pink);bc.drawOval(x+9f*s,y-83f*s,x+29f*s,y-70f*s,p);rect(bc,x+26f*s,y-79f*s,x+39f*s,y-73f*s,Color.rgb(35,28,35));rect(bc,x+17f*s,y-79f*s,x+21f*s,y-75f*s,Color.YELLOW);rect(bc,x-10f*s,y-42f*s,x+14f*s,y-25f*s,Color.rgb(215,49,106));rect(bc,x-13f*s,y-20f*s,x-9f*s,y,pink);rect(bc,x+9f*s,y-20f*s,x+13f*s,y,pink);rect(bc,x-17f*s,y-2f*s,x-7f*s,y+2f*s,Color.rgb(42,34,40));rect(bc,x+8f*s,y-2f*s,x+18f*s,y+2f*s,Color.rgb(42,34,40));if(b.boss){rect(bc,x-31f*s,y-91f*s,x+31f*s,y-86f*s,Color.rgb(72,25,29));txt(bc,"ALPHA",x,y-94f*s,7f,Color.YELLOW,true)}}
  fun beer(q:Beer){val x=q.x-cam;if(x !in -30f..670f)return;val y=G-31f+sin(t*5f+q.x)*3f;rect(bc,x-8f,y-15f,x+8f,y+15f,Color.rgb(225,225,213));rect(bc,x-8f,y-7f,x+8f,y+8f,Color.rgb(30,99,181));rect(bc,x-5f,y-18f,x+5f,y-14f,Color.rgb(180,180,170));txt(bc,"BEER",x,y+3f,5f,Color.YELLOW,true)}
  fun hud(){rect(bc,0f,0f,640f,38f,Color.rgb(15,14,31));txt(bc,"HOLD MY BEER",10f,14f,10f,Color.YELLOW);rect(bc,10f,20f,188f,31f,Color.rgb(54,39,51));rect(bc,12f,22f,12f+174f*hp/100f,29f,if(hp>30)Color.rgb(48,215,75) else Color.RED);txt(bc,"FLORIDA MAN",320f,16f,15f,Color.YELLOW,true);txt(bc,"POOL NOODLE PANIC • LEVEL 1 • WAVE $wave/3",320f,30f,7f,Color.WHITE,true);p.textAlign=Paint.Align.RIGHT;txt(bc,"SCORE $score",630f,14f,9f,Color.WHITE,false);p.textAlign=Paint.Align.RIGHT;bc.drawText("COLD ONES x $cans",630f,29f,p);p.textAlign=Paint.Align.LEFT;if(combo>1)txt(bc,"COMBO x$combo",505f,48f,9f,Color.YELLOW)}
  fun controls(){col(Color.argb(135,10,18,28));bc.drawCircle(48f,322f,27f,p);bc.drawCircle(558f,322f,23f,p);bc.drawCircle(610f,322f,23f,p);txt(bc,"JUMP",558f,325f,8f,Color.WHITE,true);txt(bc,"WHACK",610f,325f,8f,Color.WHITE,true)}
  fun panel(a:String,b:String){rect(bc,105f,126f,535f,220f,Color.argb(225,13,13,26));rect(bc,109f,130f,531f,216f,Color.rgb(34,29,57));txt(bc,a,320f,165f,20f,Color.YELLOW,true);txt(bc,b,320f,193f,10f,Color.WHITE,true)}
  fun reset(){px=105f;py=G;vy=0f;cam=0f;hp=100;score=0;cans=0;dead=false;won=false;combo=0;birds.clear();birds.addAll(listOf(Bird(470f,2,2),Bird(760f,2,2),Bird(1080f,3,3),Bird(1450f,3,3),Bird(1880f,4,4),Bird(2470f,12,12,true)));beers.clear();beers.addAll(listOf(Beer(650f),Beer(1330f),Beer(2050f)))}
  override fun onTouchEvent(e:MotionEvent):Boolean{when(e.actionMasked){MotionEvent.ACTION_DOWN,MotionEvent.ACTION_POINTER_DOWN->{val i=e.actionIndex;val id=e.getPointerId(i);val x=e.getX(i)/width*W;val y=e.getY(i)/height*H;if(!started||dead||won){if(dead||won)reset();started=true;return true};if(x<130f&&y>270f){joyId=id;joy=((x-48f)/48f).coerceIn(-1f,1f)}else if(x>585f&&y>285f){attack=.2f;attackId++}else if(x>525f&&y>285f&&py>=G-1f){vy=-330f}};MotionEvent.ACTION_MOVE->{if(joyId>=0)for(i in 0 until e.pointerCount)if(e.getPointerId(i)==joyId){val x=e.getX(i)/width*W;joy=((x-48f)/48f).coerceIn(-1f,1f)}};MotionEvent.ACTION_UP,MotionEvent.ACTION_POINTER_UP,MotionEvent.ACTION_CANCEL->{if(e.getPointerId(e.actionIndex)==joyId){joyId=-1;joy=0f}}};return true}
 }
}